"""D08 smoke/full report tables + example plots (auto-generated; no hand-typed numbers).

Usage (repo root):  python scripts/d08_report.py --tag smoke_v1 [--compare-interim DIR --compare-processed DIR]
Writes reports/D08_fallalld_<tag>_tables.md and reports/figures/D08_<tag>/. Refuses to overwrite.
"""
import argparse
import json
import sys
from pathlib import Path

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402

REPO = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(REPO / "src"))
sys.path.insert(0, str(REPO / "scripts"))
from wearsafe import features as F  # noqa: E402
from d02_smoke_report import md  # noqa: E402

VERSIONS = ("unclipped", "e4_clipped")
ROLE_COLOR = {"fall_positive": "tab:red", "fall_clip_context": "tab:gray", "adl": "tab:blue",
              "hard_negative_probe": "tab:orange", "label_uncertain_fall": "tab:purple"}


def plot_record(sig, win, record_id, sid, path):
    fig, axes = plt.subplots(3, 1, figsize=(12, 7), sharex=True, gridspec_kw={"height_ratios": [3, 3, 1.4]})
    for ax, v in zip(axes[:2], VERSIONS):
        la = pd.read_parquet(sig / v / f"{sid}.parquet")
        g = la[la.record_id == record_id]
        mag = np.sqrt(g.x ** 2 + g.y ** 2 + g.z ** 2)
        ax.plot(g.timestamp, mag / 9.80665, lw=0.8, color="0.2")
        s = g.acc_saturated.to_numpy()
        ax.plot(g.timestamp[s], (mag / 9.80665)[s], "r.", ms=3, label="acc_saturated")
        ax.set_ylabel(f"|a| (g)\n{v}")
        ax.axvline(10.0, color="r", ls="--", lw=0.8)
        if s.any():
            ax.legend(loc="upper right", fontsize=8)
    w = win[win.record_id == record_id]
    for i, r in enumerate(w.itertuples()):
        y = i % 2
        axes[2].plot([r.window_start, r.window_end], [y, y], lw=6, color=ROLE_COLOR[r.window_role],
                     solid_capstyle="butt")
    axes[2].set_ylim(-0.7, 1.7)
    axes[2].set_yticks([])
    axes[2].set_ylabel("windows")
    axes[2].set_xlabel("time in clip (s); red dashed = protocol t* = 10.0 s; window colours: red = fall_positive, "
                       "grey = fall_clip_context, blue = adl, orange = probe")
    fig.suptitle(f"{record_id}: {w.original_label.iat[0]}")
    fig.tight_layout()
    fig.savefig(path, dpi=100)
    plt.close(fig)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--tag", required=True)
    ap.add_argument("--interim-root", default="data/interim/fallalld")
    ap.add_argument("--processed-root", default="data/processed")
    ap.add_argument("--compare-interim", default=None)
    ap.add_argument("--compare-processed", default=None)
    args = ap.parse_args()
    out = REPO / f"reports/D08_fallalld_{args.tag}_tables.md"
    figs = REPO / f"reports/figures/D08_{args.tag}"
    for p in (out, figs):
        if p.exists():
            raise FileExistsError(f"{p} exists; refusing to overwrite")
    figs.mkdir(parents=True)
    interim, proc = REPO / args.interim_root, REPO / args.processed_root
    sig = interim / f"normalized_signals_{args.tag}"
    wdir = interim / f"windows_{args.tag}"
    win = pd.read_parquet(wdir / "windows.parquet")
    recs = pd.read_csv(REPO / f"metadata/fallalld_records_{args.tag}.csv")
    frun = proc / f"fallalld_features_{args.tag}_run"
    feats = {(v, fv): pd.read_parquet(proc / "motion" / f"fallalld_{v}_features-{fv}_{args.tag}.parquet")
             for v in VERSIONS for fv in ("v1", "v2")}
    checks = pd.concat([pd.DataFrame(json.loads((wdir / "checks.json").read_text())).assign(stage="build"),
                        pd.DataFrame(json.loads((frun / "checks.json").read_text())).assign(stage="features")])
    S = [f"# D08 FallAllD wrist tables ({args.tag}) — auto-generated by scripts/d08_report.py\n"]
    S.append("## 1. Invariant checks\n")
    S.append(f"{int(checks.passed.sum())} of {len(checks)} checks passed.\n")
    S.append(md(checks.assign(passed=checks.passed.map({True: "pass", False: "FAIL"}))[["stage", "scope", "check", "passed"]]) + "\n")

    S.append("## 2. Records and windows per subject (class balance)\n")
    t = win.groupby(["subject_id", "window_role"]).size().unstack(fill_value=0).reset_index()
    for c in ROLE_COLOR:
        if c not in t:
            t[c] = 0
    t["train_candidate"] = t.fall_positive + t.adl
    t["positive:negative"] = t.apply(lambda r: f"1:{r.adl / r.fall_positive:.1f}" if r.fall_positive else "no positives",
                                     axis=1)
    rc = recs.groupby(["subject_id", "kind"]).size().unstack(fill_value=0).reset_index()
    S.append(md(rc) + "\n")
    S.append(md(t[["subject_id", "fall_positive", "fall_clip_context", "label_uncertain_fall", "adl",
                   "hard_negative_probe", "train_candidate", "positive:negative"]]) + "\n")
    S.append("### 2b. Deduplicated view (one clip per overlap group; user decision 4)\n")
    d = recs.assign(rep=recs.dedup_representative.astype(bool))
    dd = d.groupby("subject_id").agg(clips=("record_id", "size"), overlap_groups=("overlap_group_id", "nunique"),
                                     clips_in_shared_groups=("overlap_group_id",
                                                             lambda s: int(s.map(s.value_counts()).gt(1).sum())))
    dw = win[win.dedup_representative].groupby(["subject_id", "window_role"]).size().unstack(fill_value=0)
    S.append(md(dd.join(dw.add_prefix("dedup_")).reset_index()) + "\n")

    S.append("## 3. e4_clipped saturation (fraction of 32 Hz samples with any axis at the E4 rail)\n")
    rows = []
    for kind, g in recs.groupby("kind"):
        rows.append({"kind": kind, "records": len(g), "median_saturated_frac": g.e4_saturated_frac.median(),
                     "mean_saturated_frac": g.e4_saturated_frac.mean(),
                     "records_with_any_saturation_pct": 100 * (g.e4_saturated_frac > 0).mean()})
    S.append(md(pd.DataFrame(rows).round(4)) + "\n")
    ps = recs.groupby(["subject_id", "kind"]).e4_saturated_frac.agg(
        records="size", mean_saturated_frac="mean",
        records_with_any_pct=lambda x: 100 * (x > 0).mean()).unstack("kind").round(4)
    ps.columns = [f"{a}_{b}" for a, b in ps.columns]
    sw = feats[("e4_clipped", "v2")].groupby(["subject_id", "window_role"]).acc_saturated_frac.apply(
        lambda x: round(100 * (x > 0).mean(), 2)).unstack("window_role").add_prefix("windows_saturated_pct_")
    S.append("Per subject (e4_clipped): records, mean saturated fraction, % records with any saturation, and % windows "
             "with any saturation by role:\n\n" + md(ps.join(sw).reset_index()) + "\n")
    rows = []
    for v in VERSIONS:
        f = feats[(v, "v2")]
        for role, g in f.groupby("window_role"):
            rows.append({"version": v, "window_role": role, "windows": len(g),
                         "median acc_mag_max (m/s²)": g.acc_mag_max.median(),
                         "windows with saturation (%)": 100 * (g.acc_saturated_frac > 0).mean(),
                         "median sat_longest_run_s": g.sat_longest_run_s.median(),
                         "median post_peak_stillness": g.post_peak_stillness.median(),
                         "median pre_peak_min_mag": g.pre_peak_min_mag.median()})
    S.append("## 4. Feature summary by window role and version (median; features_v2 table)\n")
    S.append(md(pd.DataFrame(rows).round(3)) + "\n")

    S.append("## 5. features_v2 NaN rates (%) by version\n")
    rows = [{"version": v, **{c: round(100 * feats[(v, "v2")][c].isna().mean(), 3) for c in F.SATURATION_FEATURE_NAMES_V2}}
            for v in VERSIONS]
    S.append(md(pd.DataFrame(rows)) + "\n")

    S.append("## 6. Edge-artefact check (REDEFINED: converted edge window vs the same window at native 238 Hz; "
             "median |relative difference| over cyclic ADL clips; limit < 1%)\n")
    S.append(md(pd.read_csv(frun / "edge_check.csv").round(5)) + "\n")

    S.append("## 7. Fall clips (this run) listed in metadata/fallalld_label_uncertain_v1.csv\n")
    lu = pd.read_csv(REPO / "metadata/fallalld_label_uncertain_v1.csv")
    o = lu[lu.record_id.isin(recs.record_id)]
    S.append(f"{len(o)} of {int((recs.kind == 'fall').sum())} smoke fall clips.\n\n"
             + (md(o[["record_id", "original_label", "status", "peak_t_238hz", "peak_t_32hz"]]) if len(o) else "") + "\n")
    S.append("## 7b. Clip-centre intensity pattern (dataset property; cyclic ADL clips; median window acc_mag_mean "
             "vs interior)\n")
    prof = pd.read_csv(frun / "clip_centre_profile.csv")
    S.append(md(prof.pivot(index="window_start", columns="version", values="pct_vs_interior").round(2).reset_index()) + "\n")

    S.append("## 8. Example clips (figures)\n")
    fall = recs[(recs.kind == "fall") & ~recs.peak_outside_positive_window & ~recs.label_uncertain].iloc[0]
    examples = [fall.record_id]
    for act in (20, 13):     # walking slowly (cyclic), sitting down (transient)
        r = recs[(recs.kind == "adl") & (recs.activity_id == act)]
        if len(r):
            examples.append(r.iloc[0].record_id)
    big = recs[recs.kind == "fall"].sort_values("e4_saturated_frac", ascending=False)
    if len(big):
        examples.append(big.iloc[0].record_id)
    for rid in dict.fromkeys(examples):
        sid = rid[:12]
        p = figs / f"{rid}.png"
        plot_record(sig, win, rid, sid, p)
        S.append(f"![{rid}](figures/D08_{args.tag}/{p.name})\n")

    if args.compare_interim and args.compare_processed:
        S.append("## 9. Determinism (independent re-run, table by table)\n")
        rows = []
        ci, cp = Path(args.compare_interim), Path(args.compare_processed)
        for v in VERSIONS:
            for f in sorted((sig / v).glob("*.parquet")):
                rows.append((f"normalized_signals/{v}/{f.name}",
                             pd.read_parquet(f).equals(pd.read_parquet(ci / f"normalized_signals_{args.tag}" / v / f.name))))
        rows.append(("windows.parquet", win.equals(pd.read_parquet(ci / f"windows_{args.tag}" / "windows.parquet"))))
        for k, f in feats.items():
            p = cp / "motion" / f"fallalld_{k[0]}_features-{k[1]}_{args.tag}.parquet"
            rows.append((p.name, f.equals(pd.read_parquet(p))))
        rows.append((f"fallalld_records_{args.tag}.csv", recs.equals(pd.read_csv(ci / f"fallalld_records_{args.tag}.csv"))))
        S.append(md(pd.DataFrame([(a, "identical" if b else "DIFFERENT") for a, b in rows], columns=["file", "result"])) + "\n")
    out.write_text("\n".join(S))
    print(f"wrote {out}")


if __name__ == "__main__":
    main()
